package dev.halloween;
import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.block.*;
import net.minecraft.util.math.*;
final class StationTrackChecks {
 static boolean done,prepared;static int waiting;static void register(){if(!Boolean.getBoolean("halloween.stationTrackTest"))return;ServerTickEvents.END_SERVER_TICK.register(server->{if(done||server.getTicks()<40)return;try{var w=server.getOverworld();var network=RailwayNetwork.get(w);if(!prepared){network.stations.clear();network.lines.clear();for(int facing=0;facing<4;facing++){var st=new RailwayNetwork.Station(800+facing,new BlockPos(facing*180,100,0),facing,0);network.stations.add(st);var path=new RailPath(RailPath.straight(st.center(-80),st.center(144)));var line=new RailwayNetwork.Line("track-check-"+facing,st.village,path.controls,20,true);network.lines.add(line);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)w.setChunkForced((st.origin.getX()>>4)+x,z,true);for(int z=-80;z<=144;z+=4)for(double lane:new double[]{-4,4}){var p=BlockPos.ofFloored(path.at(path.closest(st.center(z)),lane));w.getChunk(p);var cp=new ChunkPos(p);w.setChunkForced(cp.x,cp.z,true);}
 for(var e:RailwayNetwork.building(w,st,"railway_station").entrySet()){w.getChunk(e.getKey());w.setBlockState(e.getKey(),e.getValue(),Block.NOTIFY_LISTENERS);}}
 prepared=true;return;}if(++waiting<60)return;for(int facing=0;facing<4;facing++){var st=network.stations.get(facing);var path=network.lines.get(facing).path;RailStationSafety.repairTracks(w,st);int count=0;for(double d=0;d<path.length;d+=4)for(double lane:new double[]{-4,4}){var point=path.at(d,lane);double localZ=point.subtract(Vec3d.of(st.origin)).dotProduct(new Vec3d(st.forward().getOffsetX(),0,st.forward().getOffsetZ()));if(localZ<0||localZ>64)continue;var p=BlockPos.ofFloored(point);if(!w.getBlockState(p).isOf(RailContent.TRACK)||!(w.getBlockEntity(p) instanceof RailTrackEntity track)||track.points.size()!=9)throw new AssertionError("missing track facing="+facing+" at "+p+" actual="+w.getBlockState(p)+" loaded="+w.isChunkLoaded(new ChunkPos(p).toLong()));var first=track.points.getFirst().add(Vec3d.of(p));var last=track.points.getLast().add(Vec3d.of(p));if(first.distanceTo(point)>.001||Math.abs(first.distanceTo(last)-4)>.01)throw new AssertionError("track geometry does not follow route");count++;}
 if(count<30)throw new AssertionError("not enough platform track segments "+count);org.slf4j.LoggerFactory.getLogger("station-track-test").info("PASS station facing {}: {} restored segments, both tracks, spline aligned",facing,count);}
 }catch(Throwable e){org.slf4j.LoggerFactory.getLogger("station-track-test").error("FAIL",e);}done=true;server.stop(false);});}
}
